/bin/bash -lc "python - <<'PY'
from pathlib import Path
import re
for f in sorted(Path('/docs').glob('*.txt')):
 s=f.read_text(); pages=re.split(r'--- page (\\d+) ---',s)
 print('\\nFILE',f.name[:-4])
 for i in range(1,len(pages),2):
  lines=pages[i+1].splitlines()
  for j,l in enumerate(lines):
   if re.search(r'california|govern|laws of|construed.*accordance',l,re.I):
    print('PAGE',pages[i],':',' '.join(lines[max(0,j-1):j+4]))
PY"

